# -*- coding: utf-8 -*-
exec(open('lib4.py',encoding='utf-8').read())
c='p5';B='CSDL 4'
S=[]
S.append(TITLE('TIN HỌC · CƠ SỞ DỮ LIỆU 4','SQL: LIÊN KẾT BẢNG<br>VÀ TRUY VẤN CON','INNER JOIN, LEFT JOIN, JOIN nhiều bảng, bí danh bảng, truy vấn con trong WHERE, IN, EXISTS, so sánh với trung bình.',['JOIN','LEFT JOIN','ON','truy vấn con','IN']))
S.append(goals(c,B,['Giải thích vì sao phải <b>liên kết bảng</b>.','Viết <b>INNER JOIN</b>, <b>LEFT JOIN</b> với điều kiện <b>ON</b>.','Dùng <b>bí danh bảng</b> và JOIN <b>nhiều bảng</b>.','Viết <b>truy vấn con</b> (subquery) trong <b>WHERE</b> với =, &gt;, <b>IN</b>.','Phân biệt kết quả các loại JOIN và tránh lỗi <b>tích Descartes</b>.'],['Liên kết bảng','INNER JOIN, LEFT JOIN','Kết hợp JOIN và nhóm','Truy vấn con','Trọng tâm, HSG']))
S.append(S2(c,B+' · 0','Dữ liệu dùng trong bài',RES(OUT(SQLRUN(SETUP,'SELECT * FROM hocsinh'),20),'HOCSINH'),RES(OUT(SQLRUN(SETUP,'SELECT * FROM lop'),20),'LOP')+KEY('Lớp <b>12D</b> chưa có học sinh nào: chi tiết này giúp phân biệt <b>INNER</b> và <b>LEFT JOIN</b>.')))
S.append(S2(c,B+' · 1','Vì sao phải liên kết bảng?',card('Thông tin nằm ở nhiều bảng',ul(['HOCSINH chỉ có <b>mã lớp</b> (12A…), không có <b>tên lớp, GVCN</b>.','Muốn in “học sinh – tên lớp – GVCN” phải <b>ghép</b> hai bảng.','Ghép dựa trên <b>khoá ngoài = khoá chính</b>.'],6)),KEY('Thiết kế tách bảng tránh dư thừa; khi cần thông tin đầy đủ thì dùng <b>JOIN</b> ghép lại <b>tại thời điểm truy vấn</b>.')+WARN('Viết <code>FROM a, b</code> mà <b>thiếu điều kiện ghép</b> sẽ ra <b>tích Descartes</b>: mọi cặp dòng (6 × 4 = 24 dòng).')))
S.append(SQ(c,B+' · 1','Tích Descartes (lỗi thường gặp)','SELECT COUNT(*) AS so_dong\nFROM hocsinh, lop',KEY('Thiếu điều kiện ghép: 6 học sinh × 4 lớp = <b>24 dòng</b> vô nghĩa.'),24))
S.append(SQ(c,B+' · 1','INNER JOIN: ghép các dòng khớp','SELECT h.hoten, l.tenlop, l.gvcn\nFROM hocsinh h\nINNER JOIN lop l ON h.lop = l.malop',KEY('<b>INNER JOIN … ON</b> chỉ giữ cặp dòng <b>thoả điều kiện</b>. <b>h, l</b> là <b>bí danh</b> bảng cho ngắn gọn.'),21))
S.append(S2(c,B+' · 1','Sơ đồ INNER JOIN',RES('<svg viewBox="0 0 520 260" style="width:100%"><g font-family="sans-serif" font-weight="800" font-size="24" text-anchor="middle"><circle cx="190" cy="125" r="100" fill="#FFCCBC" fill-opacity=".8" stroke="#D84315" stroke-width="4"/><circle cx="330" cy="125" r="100" fill="#BBDEFB" fill-opacity=".8" stroke="#1565C0" stroke-width="4"/><path d="M260 38 A100 100 0 0 1 260 212 A100 100 0 0 1 260 38" fill="#FFB300" stroke="#0B2545" stroke-width="3"/><text x="130" y="130" fill="#0B2545">HOCSINH</text><text x="395" y="130" fill="#0B2545">LOP</text><text x="260" y="124" fill="#0B2545" font-size="20">khớp</text><text x="260" y="150" fill="#0B2545" font-size="20">ON</text></g><text x="260" y="250" text-anchor="middle" font-size="22" font-weight="800" fill="#D84315">INNER JOIN = phần giao</text></svg>','Giao hai tập'),card('Quy tắc',ul(['Chỉ lấy dòng <b>có ở cả hai bảng</b> theo điều kiện ON.','Lớp <b>12D</b> (không có học sinh) <b>không xuất hiện</b>.'],6))))
S.append(SQ(c,B+' · 2','LEFT JOIN: giữ mọi dòng bảng trái','SELECT l.malop, l.tenlop, h.hoten\nFROM lop l\nLEFT JOIN hocsinh h ON h.lop = l.malop',KEY('<b>LEFT JOIN</b> giữ <b>mọi dòng bảng bên trái</b> (LOP); lớp không có học sinh vẫn hiện với giá trị <b>NULL</b> (12D).'),21))
S.append(SQ(c,B+' · 2','Tìm dòng “không có đối ứng”','SELECT l.malop, l.tenlop\nFROM lop l\nLEFT JOIN hocsinh h ON h.lop = l.malop\nWHERE h.mahs IS NULL',KEY('Mẹo kinh điển: <b>LEFT JOIN + WHERE … IS NULL</b> tìm bản ghi <b>không có</b> ở bảng kia (lớp chưa có học sinh).'),21))
S.append(TB(c,B+' · 2','Các loại JOIN',['Loại','Kết quả','Dòng không khớp'],[['<b>INNER JOIN</b>','cặp dòng thoả ON','bị bỏ'],['<b>LEFT JOIN</b>','mọi dòng bảng trái + khớp bên phải','bên trái giữ, bên phải = NULL'],['<b>RIGHT JOIN</b>','mọi dòng bảng phải','bên phải giữ, bên trái = NULL'],['<b>FULL JOIN</b>','mọi dòng cả hai','không khớp giữ, ô thiếu = NULL'],['<b>CROSS JOIN</b>','tích Descartes','không có điều kiện']],note=KEY('Đề thi thường dùng <b>INNER JOIN</b> và <b>LEFT JOIN</b>. A LEFT JOIN B tương đương B RIGHT JOIN A.')))
S.append(SQ(c,B+' · 2','JOIN kèm lọc và sắp xếp','SELECT h.hoten, l.tenlop, h.diemtb\nFROM hocsinh h\nJOIN lop l ON h.lop = l.malop\nWHERE l.gvcn LIKE \'Co%\'\nORDER BY h.diemtb DESC',KEY('Có thể dùng <b>WHERE, ORDER BY</b> như bình thường sau JOIN; <b>JOIN</b> mặc định là INNER.'),20))
S.append(SQ(c,B+' · 3','JOIN kết hợp GROUP BY','SELECT l.tenlop, COUNT(h.mahs) AS so_hs,\n       ROUND(AVG(h.diemtb),2) AS tb\nFROM lop l\nLEFT JOIN hocsinh h ON h.lop = l.malop\nGROUP BY l.malop, l.tenlop',KEY('Dùng <b>LEFT JOIN + COUNT(h.mahs)</b> để lớp <b>0 học sinh</b> vẫn hiện (COUNT cột bỏ NULL → 0); <b>COUNT(*)</b> sẽ đếm sai thành 1.'),19))
S.append(SQ(c,B+' · 3','Số học sinh mỗi giáo viên chủ nhiệm','SELECT l.gvcn, COUNT(*) AS so_hs\nFROM hocsinh h JOIN lop l ON h.lop = l.malop\nGROUP BY l.gvcn\nHAVING COUNT(*) >= 2\nORDER BY so_hs DESC',KEY('Thứ tự: ghép bảng → nhóm theo GVCN → giữ nhóm ≥ 2 → sắp xếp.'),20))
S.append(S2(c,B+' · 3','JOIN ba bảng: thư viện',CODE('SELECT bd.hoten, s.tensach, m.ngaymuon\nFROM muon m\nJOIN bandoc bd ON m.mabd = bd.mabd\nJOIN sach s    ON m.masach = s.masach\nWHERE m.ngaytra IS NULL;',20),card('Cách đọc',ul(['<b>muon</b> là bảng trung gian chứa hai khoá ngoài.','Mỗi <b>JOIN … ON</b> thêm một bảng.','<code>ngaytra IS NULL</code>: sách <b>chưa trả</b>.'],6))+KEY('JOIN nhiều bảng: ghép lần lượt, mỗi lần một điều kiện <b>ON</b>.')))
S.append(S2(c,B+' · 4','Truy vấn con (subquery)',card('Khái niệm',ul(['<b>Truy vấn con</b>: câu SELECT <b>lồng trong ngoặc</b> trong câu truy vấn khác.','Chạy <b>trước</b>, kết quả dùng cho truy vấn ngoài.','Thường đặt trong <b>WHERE</b>.'],6)),KEY('Dùng khi điều kiện cần một giá trị <b>phải tính trước</b>: “điểm cao hơn trung bình”, “lớp có nhiều học sinh nhất”.')))
S.append(SQ(c,B+' · 4','Truy vấn con trả một giá trị','SELECT hoten, diemtb\nFROM hocsinh\nWHERE diemtb > (SELECT AVG(diemtb) FROM hocsinh)',KEY('Truy vấn trong ngoặc cho <b>7,75</b> (trung bình); truy vấn ngoài lấy học sinh <b>điểm cao hơn 7,75</b>. Hàm tổng hợp <b>không viết trực tiếp</b> trong WHERE.'),21))
S.append(SQ(c,B+' · 4','Học sinh có điểm cao nhất','SELECT hoten, diemtb FROM hocsinh\nWHERE diemtb = (SELECT MAX(diemtb) FROM hocsinh)',KEY('Có thể có <b>nhiều học sinh cùng điểm cao nhất</b>; cách này lấy tất cả (khác <code>ORDER BY … LIMIT 1</code> chỉ lấy một).'),21))
S.append(SQ(c,B+' · 4','Truy vấn con trả nhiều giá trị: IN','SELECT hoten, lop FROM hocsinh\nWHERE lop IN (SELECT malop FROM lop\n              WHERE gvcn LIKE \'Co%\')',KEY('<b>IN (truy vấn con)</b>: giá trị thuộc <b>tập kết quả</b> trong ngoặc. Ở đây: học sinh thuộc lớp có <b>GVCN là cô</b>.'),20))
S.append(SQ(c,B+' · 4','NOT IN: không thuộc','SELECT malop, tenlop FROM lop\nWHERE malop NOT IN (SELECT lop FROM hocsinh)',KEY('Lớp <b>chưa có học sinh</b>: cách khác của LEFT JOIN … IS NULL. Chú ý: nếu tập con chứa <b>NULL</b>, NOT IN có thể không trả dòng nào.'),21))
S.append(SQ(c,B+' · 4','EXISTS: tồn tại','SELECT malop, tenlop FROM lop l\nWHERE EXISTS (SELECT 1 FROM hocsinh h\n              WHERE h.lop = l.malop\n                AND h.diemtb >= 9)',KEY('<b>EXISTS</b> đúng nếu truy vấn con trả về <b>ít nhất một dòng</b>: lớp có học sinh điểm ≥ 9.'),20))
S.append(SQ(c,B+' · 4','Truy vấn con trong FROM','SELECT lop, tb FROM (\n  SELECT lop, ROUND(AVG(diemtb),2) AS tb\n  FROM hocsinh GROUP BY lop\n) t\nWHERE tb > 7.6',KEY('Truy vấn con làm “bảng tạm” trong <b>FROM</b>, bắt buộc có <b>bí danh</b> (t). Cho phép lọc trên cột tính toán.'),20))
S.append(TB(c,B+' · 4','JOIN hay truy vấn con?',['Tình huống','Nên dùng'],[['Cần cột từ <b>cả hai bảng</b>','<b>JOIN</b>'],['Chỉ cần lọc theo bảng khác','<b>IN / EXISTS</b> (hoặc JOIN)'],['So với trung bình/max toàn bảng','<b>truy vấn con</b> trả một giá trị'],['Tìm bản ghi không có đối ứng','<b>LEFT JOIN … IS NULL</b> hoặc NOT EXISTS']],note=KEY('Nhiều bài làm được bằng cả hai cách; JOIN thường <b>nhanh hơn</b>, truy vấn con thường <b>dễ đọc</b>.')))
S+=END(c,B,['<b>JOIN … ON khoá_ngoài = khoá_chính</b>; thiếu ON → tích Descartes.','<b>INNER JOIN</b> giữ dòng khớp; <b>LEFT JOIN</b> giữ hết bảng trái (NULL nếu không khớp).','<b>LEFT JOIN … WHERE x IS NULL</b> tìm bản ghi không có đối ứng.','Truy vấn con: trả một giá trị (=, &gt;), nhiều giá trị (<b>IN</b>), tồn tại (<b>EXISTS</b>).','Đếm với LEFT JOIN: dùng <b>COUNT(cột)</b> bảng phải, không dùng COUNT(*).'],[('Cột từ hai bảng','JOIN … ON'),('Giữ mọi dòng bảng trái','LEFT JOIN'),('Lớn hơn trung bình','(SELECT AVG(…))'),('Thuộc tập','IN (SELECT …)')],'Quên điều kiện ON hoặc điều kiện ON sai gây kết quả nhân bản.',['<b>ON</b> lọc <b>khi ghép</b>; <b>WHERE</b> lọc <b>sau ghép</b>. Với LEFT JOIN đặt điều kiện bảng phải trong WHERE sẽ biến thành INNER.','<b>NOT IN</b> với NULL cho kết quả bất ngờ; ưu tiên NOT EXISTS.','Truy vấn con tương quan chạy <b>lại cho mỗi dòng</b> ngoài.','Self-join: ghép bảng với <b>chính nó</b> (nhân viên – quản lí).'],['<b>UNION</b> gộp kết quả hai truy vấn.','<b>View</b>: lưu truy vấn thành bảng ảo.','<b>CTE</b> (WITH …) làm truy vấn dễ đọc.'],
 [('Viết truy vấn in họ tên học sinh và tên lớp.',),('Viết truy vấn liệt kê các lớp chưa có học sinh (hai cách).',),('Viết truy vấn tìm học sinh có điểm thấp hơn điểm trung bình của cả trường.',),('INNER JOIN và LEFT JOIN khác nhau thế nào?',),('Viết truy vấn đếm số học sinh theo tên lớp, kể cả lớp 0 học sinh.',)],
 [('<code>SELECT h.hoten, l.tenlop FROM hocsinh h JOIN lop l ON h.lop = l.malop;</code>',),('<code>… LEFT JOIN … WHERE h.mahs IS NULL</code> hoặc <code>WHERE malop NOT IN (SELECT lop FROM hocsinh)</code> → '+SQL1('SELECT malop FROM lop WHERE malop NOT IN (SELECT lop FROM hocsinh)'),),('<code>WHERE diemtb &lt; (SELECT AVG(diemtb) FROM hocsinh)</code> → '+SQL1('SELECT hoten FROM hocsinh WHERE diemtb < (SELECT AVG(diemtb) FROM hocsinh)'),),('INNER chỉ giữ dòng <b>khớp</b>; LEFT giữ <b>mọi dòng bảng trái</b>, phần không khớp là NULL.',),('<code>SELECT l.tenlop, COUNT(h.mahs) FROM lop l LEFT JOIN hocsinh h ON h.lop=l.malop GROUP BY l.malop</code>',)],
 [('Viết truy vấn tên lớp có điểm trung bình cao nhất (không dùng LIMIT).',),('Viết truy vấn các học sinh cùng lớp với bạn “An”.',),('Cho 4 bảng: SV, LOP, MON, DIEM(masv, mamon, diem). Viết truy vấn tên sinh viên có điểm môn “Tin” ≥ 8.',),('So sánh hai kết quả: <code>SELECT COUNT(*) FROM lop l LEFT JOIN hocsinh h ON h.lop=l.malop</code> và <code>SELECT COUNT(h.mahs) FROM …</code>.',),('Tại sao <code>SELECT * FROM lop LEFT JOIN hocsinh h ON h.lop = lop.malop WHERE h.diemtb &gt; 8</code> không giữ được lớp 12D?',),('Viết truy vấn tìm học sinh có điểm cao hơn mọi học sinh lớp 12B.',)],
 [('<code>… GROUP BY lop HAVING AVG(diemtb) = (SELECT MAX(tb) FROM (SELECT AVG(diemtb) tb FROM hocsinh GROUP BY lop) t)</code> → lớp: '+SQL1("SELECT lop FROM hocsinh GROUP BY lop HAVING AVG(diemtb) = (SELECT MAX(tb) FROM (SELECT AVG(diemtb) tb FROM hocsinh GROUP BY lop))"),),
  ('<code>SELECT hoten FROM hocsinh WHERE lop = (SELECT lop FROM hocsinh WHERE hoten = \'An\') AND hoten &lt;&gt; \'An\'</code> → '+SQL1("SELECT hoten FROM hocsinh WHERE lop = (SELECT lop FROM hocsinh WHERE hoten = 'An') AND hoten <> 'An'"),),
  ('<code>SELECT s.ten FROM sv s JOIN diem d ON d.masv=s.masv JOIN mon m ON m.mamon=d.mamon WHERE m.tenmon=\'Tin\' AND d.diem&gt;=8</code>',),
  ('Số dòng LEFT JOIN: '+SQL1('SELECT COUNT(*) FROM lop l LEFT JOIN hocsinh h ON h.lop=l.malop')+' (có dòng của 12D); COUNT(h.mahs): '+SQL1('SELECT COUNT(h.mahs) FROM lop l LEFT JOIN hocsinh h ON h.lop=l.malop')+' (bỏ NULL).',),
  ('Điều kiện <code>h.diemtb &gt; 8</code> trong WHERE loại các dòng NULL (12D) → thành INNER. Muốn giữ, đưa điều kiện vào <b>ON</b>.',),
  ('<code>WHERE diemtb &gt; (SELECT MAX(diemtb) FROM hocsinh WHERE lop=\'12B\')</code> → '+SQL1("SELECT hoten FROM hocsinh WHERE diemtb > (SELECT MAX(diemtb) FROM hocsinh WHERE lop='12B')")+' (hoặc dùng <code>&gt; ALL</code> ở hệ hỗ trợ).',)],hper=2)
mkdeck('c4.html','CSDL 4 · SQL liên kết bảng và truy vấn con',S)
